		["Remember this answer"] = "记住此选择",
		["Reminders appear at most once every two weeks. Joining is optional."] = "提醒最多每两周出现一次，加入完全自愿。",
		["Remote name"] = "远程调用名称",
		["Remote spy"] = "远程调用监视",
		["Remove "] = "移除 ",
		["Remove a plugin: unregisters its commands from Infinite Yield and deletes its .iy file. Accepts the name with or without the .iy ending."] = "移除插件：从 Infinite Yield 注销其命令并删除 .iy 文件。名称可带或不带 .iy 后缀。",
		["Remove folder"] = "删除文件夹",
