		["Star us on GitHub"] = "在 GitHub 上给个 Star",
		["Start UAI Relay on this phone. The script hands long provider requests to it, so the executor's request limit cannot cut them off. Pairing is automatic; no token copying."] = "在这台手机上启动 UAI Relay。脚本会把耗时较长的模型请求交给它，避免被执行器的请求时限打断。配对自动完成，无需复制令牌。",
		["Start a background loop cycling through supplied Roblox chat messages. Returns immediately. Stop with chat_loop_stop."] = "在后台循环发送给定的 Roblox 聊天消息。立即返回。用 chat_loop_stop 停止。",
		["Start a self-contained task in a background subagent and immediately receive its id. Keep doing your own independent work while it runs; check agent_status periodically and collect its report before your final answer. Give each worker a distinct scope and avoid concurrent edits to the same file or runtime state. A subagent cannot ask questions, so include the full task and completion criteria. Set background=false only when this tool call must wait for the report."] = "在后台子代理中启动独立任务，并立即获得其 id。它运行期间继续做自己独立的工作；定期查看 agent_status，并在最终回答前收集报告。给每个执行者明确的范围，避免并发修改同一文件或运行时状态。子代理无法提问，因此要写全任务与完成标准。仅当必须等待报告时才设 background=false。",
		["Start an empty replay draft?"] = "新建空白重放草稿？",
		["Start an independent AI chatbot in Roblox chat using the currently selected provider/model. Maintains its own conversation memory and replies to new player messages without keeping this agent turn open. Batches rapid messages, ignores self/system echoes, and suppresses duplicate inputs and repeated replies. Do not also reply with chat_send. Stop/status through chat_loop_stop/chat_loop_status."] = "用当前选中的提供商/模型在 Roblox 聊天中启动独立 AI 聊天机器人。它维护自己的对话记忆并回复新玩家消息，且不占用本回合。会合并密集消息、忽略自己与系统回声、抑制重复输入与重复回复。不要再通过 chat_send 回复。用 chat_loop_stop/chat_loop_status 停止或查看状态。",
		["Start chatting"] = "开始对话",
		["Start keyword-based auto-replies to other players in Roblox chat. Uses supplied rules, ignores self/system messages, and sends at most one reply per interval. No ongoing inference requests."] = "按关键词向其他玩家自动回复。使用给定规则，忽略自己与系统消息，每个间隔最多回复一次。不会持续调用模型。",
		["Start over"] = "重新开始",
		["Start with the sidebar collapsed"] = "启动时收起侧栏",
		["Status, quiz scores, and stop controls"] = "状态、测验得分与停止控制",
		["Step limit"] = "步数上限",
		["Stop"] = "停止",
		["Stop a managed chat loop immediately, or use id='all' to stop every chat loop. An already submitted message cannot be recalled."] = "立即停止一个受管理的聊天循环，或用 id='all' 停止全部。已提交的消息无法撤回。",
		["Stop all"] = "全部停止",
		["Stop condition"] = "停止条件",
		["Stops the current turn, drains every timer and input handler, "] = "停止当前回合，释放所有计时器与输入监听，",
		["Stops the current turn, drains every timer and input handler, saves your settings and removes the interface. Run the loader again to come back."] = "停止当前回合、释放所有计时器与输入监听、保存设置并移除界面。重新运行加载器即可恢复。",
		["Streamed replies carry reasoning text and token counts. Turning this off always takes effect; turning it on only does while Settings has streaming on."] = "流式回复会携带推理文本与 Token 计数。关闭总是生效；开启仅在设置中也开启流式时有效。",
